#[using="Type"] Lemma art_clspop_B : forall regs (M rom : word -> option byte) (sp tp key tsd ctx t r c spb qs au mu km nf sz new rem m1 m2 sv addr shb : Z),
  addr = spb + c * 2 ^ 32 + mu -> shb = 2147450880 + 8192 * qs + c * 2 ^ 29 + 32768 * km ->
  getr regs 1 = Z_to_bv 64 0x8ebec -> getr regs 2 = Z_to_bv 64 (sp - 64 - 128) -> getr regs 4 = Z_to_bv 64 tp -> getr regs 8 = Z_to_bv 64 262144 ->
  getr regs 10 = Z_to_bv 64 addr -> getr regs 21 = Z_to_bv 64 sz -> getr regs 22 = Z_to_bv 64 1321624 ->
  0x69c000 + 464 <= sp -> sp < 2 ^ 47 -> 1 <= c <= 30 -> spb = 65536 * qs -> mu = 262144 * km -> 0 <= km -> kHighMemBeg <= spb -> spb + 2 ^ 37 < 2 ^ 47 ->
  mu + 2 ^ 18 <= 3758096384 -> 32 <= sz <= 65536 -> 0 <= au -> au <= mu -> mu + 262144 - au = new * sz + rem -> 0 <= rem < sz -> 0 <= new -> 0 <= nf < 2 ^ 32 ->
  0 <= m1 < 2 ^ 64 -> 0 <= m2 < 2 ^ 64 -> 0 <= sv < 2 ^ 64 ->
  4096 <= t -> t + 4096 <= sp - 464 -> (t + 2792) mod 8 = 0 -> 0x69c000 <= r -> r + 128 <= sp - 464 -> apart t 4096 r 128 ->
  0x10100 <= tp -> tp + 8 <= 0x69c000 -> 0x10000 <= tsd -> tsd + 1024 <= 0x69c000 -> 4096 <= ctx -> ctx + 4096 <= sp - 464 ->
  apart shb 32768 t 4096 -> apart shb 32768 r 128 -> apart shb 32768 ctx 4096 -> shb + 32768 <= sp - 464 ->
  wrA M (sp - 464) 400 -> wrA M shb 32768 -> wrA M (t + 2872) 16 -> wrA M (t + 2792) 8 -> wrA M r 128 ->
  art_layout M -> art_tsd M tp key tsd ctx t ->
  cellA M (sp - 64 - 8) 8 0x589c4 -> cellA M (sp - 64 - 16) 8 r -> cellA M (sp - 64 - 24) 8 (t + 2768) -> cellA M (sp - 64 - 32) 8 (spb + c * 2 ^ 32) ->
  cellA M (sp - 64 - 40) 8 0x96da4 -> cellA M (sp - 64 - 48) 8 262144 -> cellA M (sp - 64 - 56) 8 addr ->
  cellA M (sp - 64 - 64) 8 (spb + c * 2 ^ 32) -> cellA M (sp - 64 - 72) 8 262144 -> cellA M (sp - 64 - 80) 8 addr ->
  cellA M 0x13d8b8 8 0x1d7c28 -> cellA M (0x1d7c28 + 144) 8 0 ->
  cellA M (t + 2872) 8 m1 -> cellA M (t + 2880) 8 m2 -> cellA M (t + 2792) 8 sv -> cellA M (r + 48) 8 mu -> cellA M (r + 32) 8 au -> cellA M (r + 16) 8 nf ->
  exists regs' M',
    msteps ASEGS (mkst regs (0x8ce30 : word) M rom) (mkst regs' (0x56568 : word) M' rom)
    /\ getr regs' 1 = (0x58a38 : bv 64)%bv /\ getr regs' 2 = Z_to_bv 64 (sp - 64) /\ getr regs' 4 = Z_to_bv 64 tp /\ getr regs' 8 = Z_to_bv 64 r
    /\ getr regs' 9 = Z_to_bv 64 (nf + new) /\ getr regs' 10 = Z_to_bv 64 1321624 /\ getr regs' 11 = Z_to_bv 64 r /\ getr regs' 12 = Z_to_bv 64 (spb + c * 2 ^ 32)
    /\ getr regs' 13 = Z_to_bv 64 (nf + new) /\ getr regs' 18 = Z_to_bv 64 (spb + c * 2 ^ 32) /\ getr regs' 19 = Z_to_bv 64 new
    /\ getr regs' 20 = Z_to_bv 64 (mu + 262144 - au) /\ getr regs' 21 = Z_to_bv 64 sz /\ getr regs' 22 = Z_to_bv 64 1321624
    /\ (forall x : reg, In x [3; 23; 24; 25; 26; 27]%bv -> getr regs' x = getr regs x)
    /\ mem_grows M M' /\ art_agree [(sp - 464, 400); (shb, 32768); (t + 2872, 16); (t + 2792, 8); (r + 48, 8)] M M'
    /\ (forall j, 0 <= j < 32768 -> cellA M' (shb + j) 1 250)
    /\ cellA M' (t + 2872) 8 (m1 + 1) /\ cellA M' (t + 2880) 8 (m2 + 262144) /\ cellA M' (t + 2792) 8 (sv + 262144) /\ cellA M' (r + 48) 8 (mu + 262144).
Proof.
